import openpyxl
from openpyxl.utils import get_column_letter
wb=openpyxl.load_workbook('/root/data/workbook.xlsx', data_only=False)
ws=wb['Data']

# print rows 18-21 columns A..N with coordinates
for r in range(18,22):
    row=[]
    for c in range(1,15):
        v=ws.cell(row=r,column=c).value
        row.append(v)
    print(r, row)

# Find year-like headers anywhere near top rows 1-30, cols 1-50
years=[]
for r in range(1,31):
    for c in range(1,60):
        v=ws.cell(row=r,column=c).value
        if isinstance(v,int) and 1900 < v < 2100:
            years.append((r,c,v))
print('Year-like cells (r<=30,c<=60):', [(r,get_column_letter(c),v) for r,c,v in years])

# Print Data row 19 H..L and row 20 H..L
for rr in [19,20]:
    print(f'Row {rr} H..L:', [ws.cell(row=rr,column=c).value for c in range(8,13)])

# Find header row by checking for 2018 in same column positions as Task headers (2018 etc) maybe present as strings
needle=2018
matches=[]
for r in range(1,60):
    for c in range(1,120):
        if ws.cell(row=r,column=c).value==needle:
            matches.append((r,c))
print('Exact 2018 matches:', [(r,get_column_letter(c)) for r,c in matches])

# also search for '2018' string
matches=[]
for r in range(1,60):
    for c in range(1,120):
        if ws.cell(row=r,column=c).value=='2018':
            matches.append((r,c))
print("String '2018' matches:", [(r,get_column_letter(c)) for r,c in matches])

# show non-empty cells in row 20 across cols A..Z
print('Non-empty row 20 A..Z:')
for c in range(1,27):
    v=ws.cell(row=20,column=c).value
    if v is not None:
        print(get_column_letter(c), c, v)

# show non-empty row 19 A..Z
print('Non-empty row 19 A..Z:')
for c in range(1,27):
    v=ws.cell(row=19,column=c).value
    if v is not None:
        print(get_column_letter(c), c, v)
